{
  "sop_id": "SOP-015",
  "title": "Invoice Verification (Three-Way Match)",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Validate GSTIN, PAN, and check duplicates",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Match invoice, PO, and GRN line by line",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Compute GST input credit and TDS",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Adjust advances and other deductions",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Prepare payment voucher and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for GRN / completion certificate",
      "role": "Executor",
      "type": "decision"
    },
    {
      "step_id": "A1",
      "name": "Incharge verification and approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Rework on rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "out-of-tolerance or high-value invoices"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Stores",
      "item": "GRN / completion certificate",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Amount mismatch",
    "Wrong quantity",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.9
}
